float bruitAleatoire(float valeur) {
    return fract(sin(valeur) * 4.3758547e4);
}

float bruitLisse(float valeur) {
    float valeurPlancher = floor(valeur);
    float fraction = fract(valeur);
    fraction = fraction * fraction * (3. - 2. * fraction);
    return mix(bruitAleatoire(valeurPlancher), bruitAleatoire(valeurPlancher + 1.), fraction);
}

float distanceCercle(vec2 position, float rayon) {
    return length(position) - rayon;
}

float distanceBoite(vec2 position, vec2 dimensions) {
    vec2 ecart = abs(position) - dimensions;
    return length(max(ecart, 0.)) + min(max(ecart.x, ecart.y), 0.);
}

float distanceTriangleEquilateral(vec2 position, float rayon) {
    const float racineTrois = sqrt(3.);
    position.x = abs(position.x) - rayon;
    position.y = position.y + rayon / racineTrois;
    if (position.x + racineTrois * position.y > 0.) position = vec2(position.x - racineTrois * position.y, -racineTrois * position.x - position.y) / 2.;
    position.x -= clamp(position.x, -2. * rayon, 0.);
    return -length(position) * sign(position.y);
}

vec4 composerForme(float distance, vec3 couleurPrimaire, vec3 couleurSecondaire, float epaisseurBord, float facteurMelange, float intensiteOmbre) {
    float opacite = 1. - smoothstep(0., epaisseurBord, distance);
    float ombre = (1. - smoothstep(0., epaisseurBord, distance)) * smoothstep(-epaisseurBord * 2.5, -epaisseurBord * .5, distance);
    vec3 couleurFin = mix(couleurPrimaire, couleurSecondaire, facteurMelange);
    couleurFin = mix(couleurFin, vec3(.02), ombre * intensiteOmbre);
    return vec4(couleurFin, opacite);
}

vec3 calculerCouleurCiel(float hauteur) {
    vec3 cielJour = vec3(.2, .45, .85);
    vec3 horizonJour = vec3(.85, .65, .55);
    float tempsFacteur = .5 + .5 * sin(iTime * .08);
    cielJour = mix(vec3(.12, .15, .45), cielJour, tempsFacteur);
    horizonJour = mix(vec3(.95, .5, .3), horizonJour, tempsFacteur);
    return mix(horizonJour, cielJour, smoothstep(.15, .85, hauteur));
}

vec4 dessinerSoleil(vec2 uv, float ratioAspect, vec2 positionSoleil) {
    vec2 pos = vec2(uv.x * ratioAspect - positionSoleil.x, uv.y - positionSoleil.y);
    float dist = length(pos) - .11;
    float halo = exp(-length(pos) * 12.) * .6 + exp(-length(pos) * 3.) * .25;
    float degrade = smoothstep(-.08, .08, pos.x * .7 + pos.y * .7);
    vec3 couleurHaute = vec3(1., .95, .5);
    vec3 couleurBasse = vec3(1., .55, .15);
    vec4 resultat = composerForme(dist, couleurHaute, couleurBasse, .006, degrade, .7);
    resultat.rgb += halo * vec3(1., .75, .35);
    resultat.a = max(resultat.a, clamp(halo, 0., 1.));
    return resultat;
}

float calculerDistanceNuages(vec2 position, float couche, float temps) {
    float distanceMin = 1e5;
    float vitesse = .05 + couche * .03;
    float echelle = .9 + couche * .3;
    vec2 posDeplacee = position + vec2(temps * vitesse, 0.);
    float indexNuage = floor(posDeplacee.x * echelle);
    for (int decalage = -2; decalage <= 2; decalage++) {
        float idNuage = indexNuage + float(decalage);
        float probabilite = bruitAleatoire(idNuage * 17.13 + couche * 31.4);
        if (probabilite < .2) continue;
        float posX = (idNuage + .5) / echelle;
        float oscillation = .015 * sin(temps * .8 + idNuage * 2.5);
        float posY = .68 + .08 * bruitAleatoire(idNuage * 3.1) - couche * .06 + oscillation;
        vec2 centreNuage = vec2(posX, posY);
        float taille = .09 + .03 * bruitAleatoire(idNuage * 5.7) + oscillation * .5;
        float tailleMoins = taille * .75;
        float tailleAutre = taille * .8;
        float dist = distanceCercle(posDeplacee - centreNuage, taille);
        dist = min(dist, distanceCercle(posDeplacee - (centreNuage + vec2(taille * .85, -.01)), tailleMoins));
        dist = min(dist, distanceCercle(posDeplacee - (centreNuage - vec2(taille * .75, -.01)), tailleAutre));
        dist = min(dist, distanceCercle(posDeplacee - (centreNuage + vec2(taille * .3, taille * .45)), taille * .6));
        dist = min(dist, distanceCercle(posDeplacee - (centreNuage - vec2(taille * .3, -taille * .35)), tailleMoins * .65));
        distanceMin = min(distanceMin, dist);
    }
    return distanceMin;
}

vec4 dessinerNuages(vec2 uv, float ratioAspect, float temps, float couche, vec2 positionSoleil) {
    vec2 pos = vec2(uv.x * ratioAspect, uv.y);
    float dist = calculerDistanceNuages(pos, couche, temps);
    if (dist > .02) return vec4(0.);
    vec2 epsilon = vec2(.002, 0.);
    vec2 normale = normalize(vec2(calculerDistanceNuages(pos + epsilon.xy, couche, temps) - calculerDistanceNuages(pos - epsilon.xy, couche, temps), calculerDistanceNuages(pos + epsilon.yx, couche, temps) - calculerDistanceNuages(pos - epsilon.yx, couche, temps)));
    vec2 dirLumiere = normalize(positionSoleil - pos);
    float eclairement = clamp(dot(normale, -dirLumiere) * .5 + .5, 0., 1.);
    float facteurOmbre = smoothstep(.3, .85, eclairement);
    vec3 couleurEclairee = mix(vec3(1., .99, .96), vec3(.88, .91, .96), couche * .4);
    vec3 couleurOmbre = mix(vec3(.55, .58, .72), vec3(.38, .42, .58), couche * .35);
    return composerForme(dist, couleurEclairee, couleurOmbre, .005, facteurOmbre, .75);
}

vec4 dessinerOiseaux(vec2 uv, float ratioAspect, float temps) {
    vec4 resultat = vec4(0.);
    for (int index = 0; index < 5; index++) {
        float idOiseau = float(index);
        float groupe = floor((temps + idOiseau * 17.1) / 14.);
        float tempsLocal = mod(temps + idOiseau * 17.1, 14.);
        float vitesse = .2 + .12 * bruitAleatoire(groupe + idOiseau * 3.1);
        float hauteurOiseau = .52 + .28 * bruitAleatoire(groupe + idOiseau * 7.9);
        float posX = ratioAspect + .4 - tempsLocal * vitesse;
        float posY = hauteurOiseau + .03 * sin(temps * 2. + idOiseau * 1.5);
        vec2 posGlobal = vec2(uv.x * ratioAspect, uv.y);
        vec2 posOiseau = posGlobal - vec2(posX, posY);
        float battement = sin(temps * 14. + idOiseau * 2.3);
        float angleAiles = battement * .55;
        vec2 posAileGauche = posOiseau - vec2(-.012, 0.);
        posAileGauche = vec2(posAileGauche.x * cos(angleAiles) - posAileGauche.y * sin(angleAiles), posAileGauche.x * sin(angleAiles) + posAileGauche.y * cos(angleAiles));
        float aileGauche = distanceBoite(posAileGauche - vec2(-.012, .004), vec2(.012, .0025)) - .001;
        vec2 posAileDroite = posOiseau - vec2(.012, 0.);
        posAileDroite = vec2(posAileDroite.x * cos(-angleAiles) - posAileDroite.y * sin(-angleAiles), posAileDroite.x * sin(-angleAiles) + posAileDroite.y * cos(-angleAiles));
        float aileDroite = distanceBoite(posAileDroite - vec2(.012, .004), vec2(.012, .0025)) - .001;
        float corps = distanceCercle(posOiseau, .006);
        float tete = distanceCercle(posOiseau - vec2(-.008, .002), .004);
        float formeTotale = min(min(corps, tete), min(aileGauche, aileDroite));
        vec3 couleurOiseau = vec3(.12, .1, .18);
        vec4 oiseauRendu = composerForme(formeTotale, couleurOiseau, couleurOiseau * .4, .002, 0., .8);
        resultat.rgb = mix(resultat.rgb, oiseauRendu.rgb, oiseauRendu.a);
        resultat.a = max(resultat.a, oiseauRendu.a);
    }
    return resultat;
}

float genererMontagnesFbm(float x, float temps) {
    float resultat = 0.;
    float amplitude = .5;
    float frequence = 1.2;
    for (int oct = 0; oct < 4; oct++) {
        resultat += bruitLisse(x * frequence + float(oct) * 1.3 + temps * .02) * amplitude;
        frequence *= 2.2;
        amplitude *= .5;
    }
    return resultat;
}

vec4 dessinerMontagnesLointaines(vec2 uv, float ratioAspect, float temps, float defilement) {
    float posHorizontale = uv.x * ratioAspect + defilement * .1;
    float bruitMontagne = genererMontagnesFbm(posHorizontale, temps);
    float hauteurMontagne = .25 + bruitMontagne * .35;
    float dist = uv.y - hauteurMontagne;
    float delta = .005;
    float pente = step(0., genererMontagnesFbm(posHorizontale - delta, temps) - genererMontagnesFbm(posHorizontale + delta, temps));
    vec3 couleurClaire = vec3(.42, .38, .62);
    vec3 couleurSombre = vec3(.2, .16, .38);
    vec4 resultat = composerForme(dist, couleurClaire, couleurSombre, .005, pente, .7);
    float hauteurNeige = hauteurMontagne + .12;
    if (uv.y > hauteurNeige) {
        float ecartNeige = uv.y - hauteurNeige;
        resultat.rgb = mix(resultat.rgb, vec3(.95, .95, 1.), smoothstep(0., .02, ecartNeige));
    }
    resultat.a *= smoothstep(.15, .3, uv.y);
    return resultat;
}

float genererCollinesProfil(float x, float temps) {
    return .1 + .35 * (.5 * bruitLisse(x * 2.5 + temps * .05) + .25 * bruitLisse(x * 5.7 - temps * .03) + .15 * bruitLisse(x * 11.3 + temps * .08));
}

vec4 dessinerCollinesEtArbres(vec2 uv, float ratioAspect, float temps, float defilement) {
    float posHorizontale = uv.x * ratioAspect + defilement * .35;
    float bruitColline = genererCollinesProfil(posHorizontale, temps);
    float hauteurColline = .05 + bruitColline;
    float distColline = uv.y - hauteurColline;
    float delta = .01;
    float pente = step(0., genererCollinesProfil(posHorizontale - delta, temps) - genererCollinesProfil(posHorizontale + delta, temps));
    vec3 couleurHerbeClaire = vec3(.28, .75, .18);
    vec3 couleurHerbeSombre = vec3(.11, .48, .07);
    vec4 resultat = composerForme(distColline, couleurHerbeClaire, couleurHerbeSombre, .004, pente, .8);
    resultat.a *= smoothstep(0., .08, uv.y);
    float espacementArbres = .45;
    float indexArbre = floor(posHorizontale / espacementArbres);
    for (int decalage = -1; decalage <= 1; decalage++) {
        float idArbre = indexArbre + float(decalage);
        if (bruitAleatoire(idArbre * 17.34) < .3) continue;
        float posArbreX = (idArbre + .2 + .6 * bruitAleatoire(idArbre * 23.1)) * espacementArbres;
        float posArbreY = .05 + genererCollinesProfil(posArbreX, temps);
        vec2 posRelative = vec2(posHorizontale, uv.y) - vec2(posArbreX, posArbreY);
        float tronc = distanceBoite(posRelative - vec2(0., .08), vec2(.015, .08)) - .003;
        float feuillagePrincipal = distanceCercle(posRelative - vec2(0., .18), .1);
        float feuillageSecondaire = (bruitAleatoire(idArbre * 31.7) > .5) ? distanceCercle(posRelative - vec2(.03, .2), .025) : 1e5;
        float distArbreTotal = min(min(tronc, feuillagePrincipal), feuillageSecondaire);
        vec3 troncCouleur = vec3(.55, .32, .12);
        vec3 troncOmbre = vec3(.3, .15, .05);
        vec3 feuillageCouleur = vec3(.2, .7, .15);
        vec3 feuillageOmbre = vec3(.05, .4, .05);
        vec3 fleurCouleur = vec3(1., .3, .2);
        float ombrageCote = step(0., posRelative.x);
        vec3 couleurBase, couleurOmbreArbre;
        if (tronc < feuillagePrincipal && tronc < feuillageSecondaire) {
            couleurBase = troncCouleur;
            couleurOmbreArbre = troncOmbre;
        } else if (feuillagePrincipal < feuillageSecondaire) {
            couleurBase = feuillageCouleur;
            couleurOmbreArbre = feuillageOmbre;
        } else {
            couleurBase = fleurCouleur;
            couleurOmbreArbre = fleurCouleur * .6;
        }
        vec4 renduArbre = composerForme(distArbreTotal, couleurBase, couleurOmbreArbre, .003, ombrageCote, .7);
        resultat.rgb = mix(resultat.rgb, renduArbre.rgb, renduArbre.a);
        resultat.a = max(resultat.a, renduArbre.a);
    }
    return resultat;
}

vec4 dessinerMoulin(vec2 uv, float ratioAspect, float temps, float defilement) {
    float intervalleMoulin = 3.2;
    float posHorizontale = uv.x * ratioAspect + defilement * .35;
    float centreMoulinX = (floor(posHorizontale / intervalleMoulin) + .5) * intervalleMoulin;
    float centreMoulinY = .05 + genererCollinesProfil(centreMoulinX, temps);
    vec2 posLocal = vec2(posHorizontale, uv.y) - vec2(centreMoulinX, centreMoulinY);
    float toit = distanceTriangleEquilateral((posLocal - vec2(0., .22)) * vec2(1.8, -1.), .18);
    toit = max(toit, -(posLocal.y - .02));
    float corpsMoulin = distanceCercle(posLocal - vec2(0., .21), .065);
    corpsMoulin = max(corpsMoulin, -(posLocal.y - .21));
    float angleAiles = temps * 1.5 + centreMoulinX;
    float distAiles = 1e5;
    vec2 axeAiles = vec2(0., .21);
    for (int i = 0; i < 4; i++) {
        float angleActuel = angleAiles + float(i) * 1.5707963;
        vec2 dirAile = vec2(cos(angleActuel), sin(angleActuel));
        vec2 deltaAxe = posLocal - axeAiles;
        float largeurAile = abs(dot(deltaAxe, vec2(-dirAile.y, dirAile.x))) - .012;
        float longueurAile = abs(dot(deltaAxe, dirAile) - .09) - .09;
        distAiles = min(distAiles, max(largeurAile, longueurAile));
    }
    float centreAxe = distanceCercle(posLocal - axeAiles, .018);
    distAiles = min(distAiles, centreAxe);
    float formeMoulinTotale = min(min(toit, corpsMoulin), distAiles);
    vec3 couleurMurailles = vec3(.8, .6, .3);
    vec3 couleurToit = vec3(.5, .2, .2);
    vec3 couleurAiles = vec3(.9, .85, .7);
    vec3 couleurSelectionnee = (toit < corpsMoulin && toit < distAiles) ? couleurMurailles : ((corpsMoulin < distAiles) ? couleurToit : couleurAiles);
    float ombrageCote = step(0., posLocal.x);
    return composerForme(formeMoulinTotale, couleurSelectionnee, couleurSelectionnee * .6, .003, ombrageCote * .3, .8);
}

vec4 dessinerHerbesPremierPlan(vec2 uv, float ratioAspect, float temps, float defilement) {
    vec4 resultat = vec4(0.);
    float posHorizontale = uv.x * ratioAspect + defilement * .8;
    float densiteHerbe = 30.;
    float indexTige = floor(posHorizontale * densiteHerbe);
    float ondulationVent = .015 * sin(uv.y * 10. + temps * 4.) * (1. - uv.y * 2.);
    for (int decalage = -1; decalage <= 1; decalage++) {
        float idTige = indexTige + float(decalage);
        float posTigeX = (idTige + .5 + .4 * (bruitAleatoire(idTige * 11.1) - .5)) / densiteHerbe;
        float hauteurTige = .06 + bruitAleatoire(idTige * 13.7) * .1;
        vec2 posRelative = vec2(posHorizontale, uv.y) - vec2(posTigeX, 0.);
        posRelative.x += ondulationVent * max(0., posRelative.y) * 2.5;
        float tigeDist = distanceBoite(posRelative - vec2(0., hauteurTige * .5), vec2(.004, hauteurTige * .5)) - .001;
        float ombrageCote = step(0., posRelative.x);
        vec3 couleurHerbe1 = vec3(.2, .75, .1);
        vec3 couleurHerbe2 = vec3(.08, .4, .05);
        vec4 renduTige = composerForme(tigeDist, couleurHerbe1, couleurHerbe2, .002, ombrageCote, .5);
        if (bruitAleatoire(idTige * 17.3) > .65) {
            float hauteurFleur = hauteurTige + .015;
            float fleurDist = distanceCercle(posRelative - vec2(0., hauteurFleur), .012);
            vec3 couleurFleur = (bruitAleatoire(idTige * 19.1) > .5) ? vec3(1., .4, .4) : vec3(.9, .9, .2);
            vec4 renduFleur = composerForme(fleurDist, couleurFleur, couleurFleur * .5, .001, 0., .3);
            renduTige.rgb = mix(renduTige.rgb, renduFleur.rgb, renduFleur.a);
            renduTige.a = max(renduTige.a, renduFleur.a);
        }
        resultat.rgb = mix(resultat.rgb, renduTige.rgb, renduTige.a);
        resultat.a = max(resultat.a, renduTige.a);
    }
    resultat.a *= smoothstep(0., .03, uv.y) * (1. - smoothstep(.18, .25, uv.y));
    return resultat;
}

vec3 appliquerVignettage(vec2 uv, vec3 couleur) {
    float facteurOmbrage = 1. - length(uv - .5) * .65;
    return couleur * max(0., facteurOmbrage);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float ratioAspect = iResolution.x / iResolution.y;
    float temps = iTime;
    float defilementPanorama = temps * .25;
    if (iMouse.z > 0.) defilementPanorama = (iMouse.x / iResolution.x) * 8.;
    vec3 cielCouleur = calculerCouleurCiel(uv.y);
    vec4 imageFinale = vec4(cielCouleur, 1.);
    vec2 positionSoleil = vec2(ratioAspect * .5, .75 + .03 * sin(temps * .4));
    vec4 soleil = dessinerSoleil(uv, ratioAspect, positionSoleil);
    imageFinale.rgb = mix(imageFinale.rgb, soleil.rgb, soleil.a);
    for (int coucheNuage = 0; coucheNuage < 2; coucheNuage++) {
        vec4 nuages = dessinerNuages(uv, ratioAspect, temps, float(coucheNuage), positionSoleil);
        imageFinale.rgb = mix(imageFinale.rgb, nuages.rgb, nuages.a);
    }
    vec4 oiseaux = dessinerOiseaux(uv, ratioAspect, temps);
    imageFinale.rgb = mix(imageFinale.rgb, oiseaux.rgb, oiseaux.a);
    vec4 montagnes = dessinerMontagnesLointaines(uv, ratioAspect, temps, defilementPanorama);
    imageFinale.rgb = mix(imageFinale.rgb, montagnes.rgb, montagnes.a);
    vec4 collines = dessinerCollinesEtArbres(uv, ratioAspect, temps, defilementPanorama);
    imageFinale.rgb = mix(imageFinale.rgb, collines.rgb, collines.a);
    vec4 moulins = dessinerMoulin(uv, ratioAspect, temps, defilementPanorama);
    imageFinale.rgb = mix(imageFinale.rgb, moulins.rgb, moulins.a);
    vec4 herbes = dessinerHerbesPremierPlan(uv, ratioAspect, temps, defilementPanorama);
    imageFinale.rgb = mix(imageFinale.rgb, herbes.rgb, herbes.a);
    imageFinale.rgb = appliquerVignettage(uv, imageFinale.rgb);
    fragColor = imageFinale;
}
